import Foundation
import PDFKit
import Vision
import AppKit

let args = CommandLine.arguments
let document = PDFDocument(url: URL(fileURLWithPath: args[1]))!
var results: [[String: Any]] = []
for index in 7..<15 {
    guard let page = document.page(at: index) else { continue }
    let image = page.thumbnail(of: NSSize(width: 2100, height: 2900), for: .mediaBox)
    var rect = CGRect(origin: .zero, size: image.size)
    guard let cgImage = image.cgImage(forProposedRect: &rect, context: nil, hints: nil) else { continue }
    let request = VNRecognizeTextRequest()
    request.recognitionLevel = .accurate
    request.usesLanguageCorrection = false
    try VNImageRequestHandler(cgImage: cgImage).perform([request])
    let lines = (request.results ?? []).compactMap { observation -> [String: Any]? in
        guard let candidate = observation.topCandidates(1).first else { return nil }
        return ["text": candidate.string, "confidence": candidate.confidence,
                "x": observation.boundingBox.origin.x, "y": observation.boundingBox.origin.y]
    }
    results.append(["pdf_page_one_based": index + 1, "ocr_not_manual_read": true, "lines": lines])
}
let data = try JSONSerialization.data(withJSONObject: results, options: [.prettyPrinted, .sortedKeys])
try data.write(to: URL(fileURLWithPath: args[2]))
print("OCR pages: \(results.count); saved \(args[2])")

from html.parser import HTMLParser
from pathlib import Path
import json

q = Path(__file__).resolve().parents[1]
class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.links = []
        self.skip = 0
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.skip += 1
        if tag in {'p', 'h1', 'h2', 'h3', 'h4', 'li', 'section', 'figure'}:
            self.parts.append('\n')
        for key, val in attrs:
            if key == 'href' and val:
                self.links.append(val)
    def handle_endtag(self, tag):
        if tag in {'script', 'style'}:
            self.skip -= 1
        if tag in {'p', 'h1', 'h2', 'h3', 'h4', 'li'}:
            self.parts.append('\n')
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)
p = Parser()
p.feed((q / 'inputs/public/PMC5800313.html').read_text())
text = '\n'.join(' '.join(line.split()) for line in ''.join(p.parts).splitlines() if line.strip())
(q / 'outputs/PMC5800313.source.txt').write_text(text + '\n')
print(json.dumps([x for x in p.links if '.pdf' in x]))

